using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class JewelUiApply {
 static void Row(string path,bool result) {
 var root=PrefabUtility.LoadPrefabContents(path);
 try {
 var sprites=AssetDatabase.LoadAllAssetsAtPath("Assets/Art/PinkJewel/JewelUI.png").OfType<Sprite>().ToArray();
 var collected=sprites.Single(s=>s.name=="JewelCollected");var empty=sprites.Single(s=>s.name=="JewelEmpty");
 var row=root.GetComponent<PinkJewelIconRow>();var settings=new SerializedObject(row);
 settings.FindProperty("collectedIcon").objectReferenceValue=collected;settings.FindProperty("emptyIcon").objectReferenceValue=empty;
 for(int i=0;i<3;i++) {
 var image=(UnityEngine.UI.Image)settings.FindProperty("icons").GetArrayElementAtIndex(i).objectReferenceValue;
 image.sprite=empty;image.color=Color.white;image.preserveAspect=true;
 var rect=image.rectTransform;rect.anchorMin=rect.anchorMax=new Vector2(0f,0.5f);rect.pivot=new Vector2(0.5f,0.5f);
 rect.sizeDelta=new Vector2(54f,87f);rect.anchoredPosition=new Vector2(27f+i*60f,0f);
 var glint=(UnityEngine.UI.Image)settings.FindProperty("glints").GetArrayElementAtIndex(i).objectReferenceValue;
 glint.rectTransform.sizeDelta=new Vector2(96f,96f);
 }
 settings.ApplyModifiedPropertiesWithoutUndo();
 Layout(root.GetComponent<RectTransform>(),result);
 PrefabUtility.SaveAsPrefabAsset(root,path);
 } finally {PrefabUtility.UnloadPrefabContents(root);}
 }
 static void Layout(RectTransform rect,bool result) {
 rect.sizeDelta=new Vector2(174f,87f);
 rect.anchorMin=rect.anchorMax=result?new Vector2(0.5f,0.5f):Vector2.zero;
 rect.pivot=result?new Vector2(0.5f,0.5f):new Vector2(0f,1f);
 rect.anchoredPosition=result?new Vector2(0f,62f):new Vector2(24f,-50f);
 }
 public static string Run() {
 if(EditorUtility.scriptCompilationFailed)throw new Exception("Compilation failed");
 Row("Assets/Prefabs/UI/PinkJewelHUD.prefab",false);Row("Assets/Prefabs/UI/PinkJewelResult.prefab",true);
 var goal=PrefabUtility.LoadPrefabContents("Assets/Prefabs/UI/GoalMenu.prefab");
 try {
 var subtitle=goal.transform.Find("CRTPresentation/PhosphorUI/SafeArea/Subtitle").GetComponent<TMPro.TMP_Text>();
 subtitle.text=string.Empty;PrefabUtility.SaveAsPrefabAsset(goal,"Assets/Prefabs/UI/GoalMenu.prefab");
 } finally {PrefabUtility.UnloadPrefabContents(goal);}
 foreach(var row in UnityEngine.Object.FindObjectsByType<PinkJewelIconRow>(FindObjectsInactive.Include)) {
 Undo.RecordObject(row.transform,"Align jewel UI");Layout((RectTransform)row.transform,row.name.StartsWith("PinkJewelResult",StringComparison.Ordinal));
 PrefabUtility.RecordPrefabInstancePropertyModifications(row.transform);
 }
 var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
 EditorSceneManager.MarkSceneDirty(scene);
 EditorSceneManager.SaveScene(scene,System.IO.Path.GetFullPath(".codex-jewel-ui-work/scene-after.unity"),true);
 return "compileFailed=False; HUD left aligned at (24,-50), icons 54x87 / 6px gaps; result centered at y62; source sheet shared; subtitle empty";
 }
